INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (1, '杠铃卧推', 'Barbell Bench Press', '杠铃', 2, '仰卧于平板凳，双脚踩实地面，肩胛骨收紧下沉，将杠铃从架上取下，控制下放至胸部中下沿后推起。', '1. 肩胛后缩下沉，保持胸部挺起；\n2. 手腕与前臂保持垂直，不要翻腕；\n3. 下放 2 秒，推起 1 秒，全程匀速。', '1. 屁股离凳借力；\n2. 杠铃砸胸弹起；\n3. 手肘完全外展成 90°，肩关节压力过大。', '胸大肌', '三角肌前束,肱三头肌', '下放时吸气，推起时呼气。', '卧推,胸,杠铃,平板', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (1, '哑铃飞鸟', 'Dumbbell Fly', '哑铃', 2, '仰卧平板凳，双手持哑铃于胸前，手肘微屈固定角度，向两侧打开至胸部有牵拉感后合拢。', '1. 手肘始终保持 15-20 度微屈；\n2. 打开幅度以肩不痛为限；\n3. 合拢时想象抱住一棵大树。', '1. 用直臂做大重量，伤肩；\n2. 下放过深；\n3. 变成推举动作。', '胸大肌', '三角肌前束', '打开吸气，合拢呼气。', '飞鸟,胸,哑铃,夹胸', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (1, '俯卧撑', 'Push-Up', '自重', 1, '双手略宽于肩撑地，身体成一直线，屈肘下放至胸部离地约一拳，再推起。', '1. 收紧核心与臀部，身体一条直线；\n2. 手肘与身体约 45 度；\n3. 全程颈部中立，眼睛看地面。', '1. 塌腰翘臀；\n2. 只做半程；\n3. 头部前探。', '胸大肌', '肱三头肌,核心', '下放吸气，推起呼气，可先从跪姿开始。', '俯卧撑,胸,自重,推', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (1, '上斜哑铃卧推', 'Incline Dumbbell Press', '哑铃', 2, '上斜凳 30-45 度，双手持哑铃于胸上方，垂直向上推起再控制下放。', '1. 凳子角度不超过 45 度，否则变成肩推；\n2. 推起时哑铃略微靠拢；\n3. 下放至胸部两侧。', '1. 角度过高；\n2. 腰部过度反弓；\n3. 哑铃相撞。', '胸大肌上束', '三角肌前束,肱三头肌', '呼吸节奏同卧推。', '上斜,卧推,胸,哑铃', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (2, '引体向上', 'Pull-Up', '自重', 3, '正握单杠略宽于肩，收肩胛发力将身体拉起至下巴过杠，缓慢下放至手臂接近伸直。', '1. 先沉肩再拉；\n2. 想象用手肘向下砸；\n3. 下放 2-3 秒，充分伸展背阔肌。', '1. 靠摆动借力；\n2. 只做上半程；\n3. 耸肩。', '背阔肌', '肱二头肌,斜方肌中下束', '上拉呼气，下放吸气。做不到可先用弹力带辅助。', '引体,背,单杠,自重', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (2, '杠铃划船', 'Barbell Row', '杠铃', 3, '俯身约 45 度，背部挺直，将杠铃沿大腿拉向腹部，再控制下放。', '1. 全程腰背挺直，核心收紧；\n2. 手肘贴身向后拉；\n3. 顶峰收缩 1 秒。', '1. 弓背；\n2. 用腰甩重量；\n3. 拉得太高到胸口。', '背阔肌', '菱形肌,斜方肌,肱二头肌', '拉起呼气，下放吸气。', '划船,背,杠铃,俯身', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (2, '高位下拉', 'Lat Pulldown', '器械', 1, '坐姿固定大腿，宽握横杆下拉至锁骨上方，控制回放。', '1. 身体略微后仰 10-15 度；\n2. 想象用手肘把杆拉下来；\n3. 回放充分伸展背阔。', '1. 拉至颈后；\n2. 用力过猛身体前后晃；\n3. 耸肩。', '背阔肌', '肱二头肌', '下拉呼气，回放吸气。', '下拉,背,器械,高位', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (2, '坐姿划船', 'Seated Cable Row', '器械', 1, '坐姿双脚踩踏板，挺胸将把手拉向腹部，肩胛后缩，控制回放。', '1. 胸口挺起，不驼背；\n2. 拉到腹部后再夹紧肩胛 1 秒；\n3. 回放时肩胛前伸但不弓腰。', '1. 用腰后仰借力；\n2. 只用手臂拉；\n3. 重量过大。', '菱形肌,背阔肌', '肱二头肌', '拉时呼气，回放吸气。', '划船,坐姿,背,器械', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (3, '杠铃深蹲', 'Barbell Squat', '杠铃', 3, '杠铃置于斜方肌上方，双脚与肩同宽，屈髋屈膝下蹲至大腿平行地面后站起。', '1. 膝盖与脚尖方向一致；\n2. 全程核心收紧、背部中立；\n3. 重心在全脚掌，脚跟不抬。', '1. 膝盖内扣；\n2. 弓腰；\n3. 半蹲就起。', '股四头肌,臀大肌', '腘绳肌,核心', '下蹲吸气，站起呼气。', '深蹲,腿,杠铃,下肢', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (3, '罗马尼亚硬拉', 'Romanian Deadlift', '杠铃', 3, '双手持杠站立，膝盖微屈固定，屈髋向后推髋下放杠铃至小腿中段，感受大腿后侧牵拉后起身。', '1. 全程背部挺直，杠铃贴近腿；\n2. 以屈髋为主，不要变深蹲；\n3. 起身时收臀发力。', '1. 弓背；\n2. 膝盖过度弯曲；\n3. 下放过低导致腰部代偿。', '腘绳肌,臀大肌', '竖脊肌', '下放吸气，起身呼气。', '硬拉,臀,腿,腿后侧', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (3, '弓箭步', 'Lunge', '自重', 2, '一脚向前跨出，屈膝下蹲至后膝接近地面，再蹬地回到起始位，左右交替。', '1. 前膝不超过脚尖太多；\n2. 躯干保持直立；\n3. 后腿膝盖朝地面而非前冲。', '1. 步幅过小；\n2. 身体前倾；\n3. 前膝内扣。', '股四头肌,臀大肌', '腘绳肌,核心', '下蹲吸气，站起呼气。', '箭步蹲,弓步,腿,臀', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (3, '臀桥', 'Glute Bridge', '自重', 1, '仰卧屈膝脚踩地，收紧臀部将髋部顶起至身体成一直线，顶点停留后放下。', '1. 用臀部发力，不要用腰；\n2. 顶点收紧臀部 2 秒；\n3. 下巴微收。', '1. 腰部过度反弓；\n2. 脚离臀太远；\n3. 速度过快。', '臀大肌', '腘绳肌,核心', '顶起呼气，放下吸气。', '臀桥,臀,髋,自重', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (4, '哑铃肩上推举', 'Dumbbell Shoulder Press', '哑铃', 2, '坐姿或站姿，双手持哑铃于耳侧，向上推起至手臂接近伸直，控制下放。', '1. 核心收紧，不塌腰；\n2. 推起时手肘略微向内收；\n3. 下放至耳侧高度即可。', '1. 腰部反弓借力；\n2. 手肘完全外展；\n3. 下放过低。', '三角肌前中束', '肱三头肌', '推起呼气，下放吸气。', '推举,肩,哑铃,三角肌', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (4, '哑铃侧平举', 'Lateral Raise', '哑铃', 1, '站立双手持哑铃于体侧，手肘微屈，向两侧举起至与肩同高，控制下放。', '1. 小重量多次数；\n2. 手肘略微弯曲并领先于手腕；\n3. 举到肩高即可，不要过肩。', '1. 耸肩；\n2. 用惯性甩；\n3. 重量过大导致代偿。', '三角肌中束', '斜方肌', '举起呼气，下放吸气。', '侧平举,肩,哑铃,中束', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (4, '面拉', 'Face Pull', '器械', 1, '绳索调至高位，双手抓绳向面部方向拉，手肘高于手腕，末端外旋肩关节。', '1. 拉向眉毛位置；\n2. 末端外旋，肩胛后缩；\n3. 轻重量高次数。', '1. 重量过大变划船；\n2. 耸肩；\n3. 身体后仰。', '三角肌后束', '菱形肌,斜方肌中束', '拉时呼气，回放吸气。', '面拉,肩,后束,绳索', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (5, '哑铃弯举', 'Dumbbell Curl', '哑铃', 1, '站立双手持哑铃，大臂贴身固定，屈肘将哑铃举至肩前后控制下放。', '1. 大臂不前后摆动；\n2. 顶峰收缩 1 秒；\n3. 下放 2-3 秒。', '1. 甩腰借力；\n2. 手腕翻折；\n3. 下放太快。', '肱二头肌', '肱肌', '举起呼气，下放吸气。', '弯举,二头,手臂,哑铃', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (5, '窄距俯卧撑', 'Close-Grip Push-Up', '自重', 2, '双手与肩同宽或略窄撑地，身体成直线，屈肘下放再推起，手肘贴近身体。', '1. 手肘贴身不外展；\n2. 核心收紧；\n3. 全程控制。', '1. 塌腰；\n2. 手肘外翻；\n3. 幅度不足。', '肱三头肌', '胸大肌,核心', '下放吸气，推起呼气。', '窄距,三头,手臂,俯卧撑', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (5, '绳索下压', 'Triceps Pushdown', '器械', 1, '面对绳索机站立，大臂贴身，握住绳索向下压至手臂伸直，控制回放。', '1. 大臂固定不晃；\n2. 伸直时收缩三头 1 秒；\n3. 回放至手肘约 90 度。', '1. 耸肩；\n2. 身体前倾借力；\n3. 大臂前后摆动。', '肱三头肌', '', '下压呼气，回放吸气。', '下压,三头,手臂,绳索', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (6, '平板支撑', 'Plank', '自重', 1, '肘部与前臂着地，身体从头到脚成一条直线，收紧核心保持静止。', '1. 臀部不塌不翘；\n2. 收紧腹部与臀部；\n3. 保持正常呼吸。', '1. 塌腰；\n2. 憋气；\n3. 抬臀。', '腹横肌', '竖脊肌,肩部', '均匀呼吸，力竭前 5 秒收尾。', '平板支撑,核心,腹,静力', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (6, '卷腹', 'Crunch', '自重', 1, '仰卧屈膝，双手轻放耳侧，用腹部力量将肩胛骨抬离地面后缓慢放下。', '1. 下颌与胸保持一拳距离；\n2. 用腹肌发力而非脖子；\n3. 下放不放松到底。', '1. 用手拉脖子；\n2. 幅度过大变成仰卧起坐；\n3. 借力弹起。', '腹直肌', '', '起身呼气，下放吸气。', '卷腹,腹肌,核心,自重', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (6, '仰卧举腿', 'Lying Leg Raise', '自重', 2, '仰卧双手放体侧，双腿并拢伸直抬起至与地面垂直后缓慢下放。', '1. 下背部贴地；\n2. 下放速度慢，避免腰部拱起；\n3. 腿不触地保持张力。', '1. 腰部离地；\n2. 用惯性甩腿；\n3. 颈部紧张。', '腹直肌下部', '髂腰肌', '抬腿呼气，下放吸气。', '举腿,下腹,核心', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (6, '俄罗斯转体', 'Russian Twist', '自重', 2, '坐姿上身后仰约 45 度，双脚可离地，双手持重物左右转体触地。', '1. 转体来自躯干而非手臂；\n2. 保持背部挺直；\n3. 控制节奏。', '1. 含胸弓背；\n2. 只动手臂；\n3. 速度过快。', '腹斜肌', '腹直肌', '转体呼气，回正吸气。', '转体,腹斜肌,核心', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (7, '开合跳', 'Jumping Jack', '自重', 1, '站立起跳，双腿分开同时双臂上举过头，再跳回并拢，连续进行。', '1. 落地屈膝缓冲；\n2. 保持节奏与呼吸；\n3. 手臂过头。', '1. 落地僵硬；\n2. 幅度过小；\n3. 憋气。', '全身', '心肺', '匀速呼吸，按时间或次数做。', '开合跳,有氧,热身,HIIT', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (7, '高抬腿', 'High Knees', '自重', 2, '原地跑动，膝盖尽量抬高至髋部高度，双臂配合摆动。', '1. 前脚掌着地；\n2. 躯干直立不后仰；\n3. 频率优先于幅度。', '1. 后仰；\n2. 脚跟着地；\n3. 手臂不摆动。', '髂腰肌,股四头肌', '心肺,核心', '短时间高强度，注意呼吸节奏。', '高抬腿,有氧,HIIT,心肺', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (7, '波比跳', 'Burpee', '自重', 3, '下蹲撑地→双腿后跳成俯撑→俯卧撑→收腿站起跳跃，一套连贯完成。', '1. 全程核心收紧；\n2. 落地缓冲；\n3. 呼吸与动作节奏匹配。', '1. 塌腰；\n2. 中间停顿过久；\n3. 落地不缓冲。', '全身', '心肺', '新手可去掉跳跃或俯卧撑环节。', '波比,有氧,HIIT,全身', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (7, '跳绳', 'Jump Rope', '跳绳', 2, '双手持绳，前脚掌轻跳，手腕发力摇绳，保持稳定节奏。', '1. 前脚掌落地；\n2. 手腕摇绳而非大臂；\n3. 跳跃高度只要过绳即可。', '1. 跳太高；\n2. 全脚掌砸地；\n3. 大臂大幅摆动。', '小腿,全身', '心肺', '每组 1-2 分钟，组间休息 30-60 秒。', '跳绳,有氧,心肺', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (7, '慢跑', 'Jogging', '自重', 1, '以能边跑边说话的强度持续跑动，心率控制在最大心率的 60-70%。', '1. 步频 170-180; \n2. 中足着地；\n3. 上身放松。', '1. 步幅过大；\n2. 手臂横摆；\n3. 一开始冲太快。', '下肢', '心肺', '热身 5 分钟，结束后拉伸。', '跑步,慢跑,有氧', 1);
INSERT INTO `exercises` (`category_id`, `name`, `name_en`, `equipment`, `difficulty`, `description`, `key_points`, `common_mistakes`, `primary_muscles`, `secondary_muscles`, `tips`, `keywords`, `is_active`) VALUES (7, '山地登山者', 'Mountain Climber', '自重', 2, '俯撑姿势，双腿交替快速向胸部收膝，像原地爬山。', '1. 臀部高度稳定；\n2. 核心收紧；\n3. 交替节奏均匀。', '1. 臀部上下起伏；\n2. 塌腰；\n3. 脚落地太重。', '核心,髋屈肌', '心肺,肩', '30 秒一组，配合呼吸。', '登山者,核心,有氧,HIIT', 1);
