INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (1, '哑铃全身力量入门', '新手第一课', '/static/covers/strength.jpg', 'https://example.com/videos/strength-1.mp4', 25, 180, 1, '哑铃', '全身', '用一对哑铃完成推、拉、蹲、髋铰链四个基本模式，建立全身力量基础。', 'Coach Leo', 0, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (1, '胸肩背分化训练（上肢日）', '一周三练进阶', '/static/covers/strength.jpg', 'https://example.com/videos/strength-2.mp4', 40, 300, 2, '哑铃,哑铃凳', '胸,肩,背', '胸推、肩推、划船三大动作组合，兼顾力量与形态。', 'Coach Leo', 1, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (1, '下肢力量强化', '深蹲硬拉组合', '/static/covers/strength.jpg', 'https://example.com/videos/strength-3.mp4', 35, 350, 3, '杠铃', '腿,臀', '以深蹲、罗马尼亚硬拉为核心的下肢力量课，适合有一定基础者。', 'Coach Amy', 2, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (2, '20 分钟居家燃脂有氧', '无需器械', '/static/covers/cardio.jpg', 'https://example.com/videos/cardio-4.mp4', 20, 220, 1, '无', '全身', '开合跳、高抬腿、登山者循环，心率稳定在燃脂区间。', 'Coach Mia', 3, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (2, '低冲击有氧塑形', '膝盖友好', '/static/covers/cardio.jpg', 'https://example.com/videos/cardio-5.mp4', 30, 260, 1, '无', '全身,臀,腿', '无跳跃动作，适合体重基数较大或膝盖需要保护的人群。', 'Coach Mia', 4, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (3, '睡前 10 分钟全身拉伸', '改善睡眠', '/static/covers/stretch.jpg', 'https://example.com/videos/stretch-6.mp4', 10, 40, 1, '瑜伽垫', '全身', '从颈部到小腿的静态拉伸序列，每个动作保持 30 秒，放松紧张肌群。', 'Coach Amy', 5, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (3, '久坐族肩颈放松', '办公室也能做', '/static/covers/stretch.jpg', 'https://example.com/videos/stretch-7.mp4', 12, 45, 1, '无', '肩,颈,背', '针对圆肩驼背与肩颈僵硬的拉伸与激活动作。', 'Coach Amy', 6, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (4, 'TABATA 四分钟极限燃脂', '4 分钟 8 轮', '/static/covers/hiit.jpg', 'https://example.com/videos/hiit-8.mp4', 4, 70, 3, '无', '全身', '20 秒全力 10 秒休息，8 轮共 4 分钟，建议做 3-5 组。', 'Coach Leo', 7, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (4, 'HIIT 燃脂 20 分钟', '中等强度循环', '/static/covers/hiit.jpg', 'https://example.com/videos/hiit-9.mp4', 20, 280, 2, '无', '全身', '6 个动作 × 4 轮，40 秒训练 20 秒休息。', 'Coach Leo', 8, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (5, '晨间唤醒流瑜伽', '15 分钟开启一天', '/static/covers/yoga.jpg', 'https://example.com/videos/yoga-10.mp4', 15, 90, 1, '瑜伽垫', '全身', '拜日式串联，配合呼吸唤醒身体与脊柱。', 'Coach Luna', 9, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (5, '髋部打开与放松', '改善骨盆灵活性', '/static/covers/yoga.jpg', 'https://example.com/videos/yoga-11.mp4', 20, 80, 2, '瑜伽垫,瑜伽砖', '髋,腿', '针对久坐导致的髋屈肌紧张，做深度髋部打开。', 'Coach Luna', 10, 1);
INSERT INTO `courses` (`category_id`, `title`, `subtitle`, `cover`, `video_url`, `duration_min`, `calories`, `difficulty`, `equipment`, `body_parts`, `description`, `coach_name`, `sort_order`, `is_published`) VALUES (5, '核心稳定流', '腹背协同', '/static/covers/yoga.jpg', 'https://example.com/videos/yoga-12.mp4', 18, 110, 2, '瑜伽垫', '核心', '以平板、船式、侧板为主的稳定序列，提升核心抗屈伸能力。', 'Coach Luna', 11, 1);
