INSERT INTO `plan_templates` (`name`, `category`, `goal`, `difficulty`, `cycle_type`, `cycle_days`, `description`, `items_json`, `is_official`) VALUES ('新手全身 3 日循环', '新手', 'keep_fit', 1, 'weekly', 7, '周一/三/五全身训练，其余日休息或轻度有氧，最适合刚开始健身的人。', '[{"day_index": 1, "items": [{"exercise": "杠铃深蹲", "sets": 3, "reps": 10, "rest_seconds": 90}, {"exercise": "俯卧撑", "sets": 3, "reps": 12, "rest_seconds": 60}, {"exercise": "高位下拉", "sets": 3, "reps": 12, "rest_seconds": 60}, {"exercise": "平板支撑", "sets": 3, "reps": 1, "duration_min": 1, "rest_seconds": 45}]}, {"day_index": 3, "items": [{"exercise": "哑铃肩上推举", "sets": 3, "reps": 12, "rest_seconds": 60}, {"exercise": "坐姿划船", "sets": 3, "reps": 12, "rest_seconds": 60}, {"exercise": "臀桥", "sets": 3, "reps": 15, "rest_seconds": 45}, {"exercise": "卷腹", "sets": 3, "reps": 15, "rest_seconds": 45}]}, {"day_index": 5, "items": [{"exercise": "罗马尼亚硬拉", "sets": 3, "reps": 10, "rest_seconds": 90}, {"exercise": "哑铃飞鸟", "sets": 3, "reps": 12, "rest_seconds": 60}, {"exercise": "面拉", "sets": 3, "reps": 15, "rest_seconds": 45}, {"exercise": "慢跑", "sets": 1, "reps": 1, "duration_min": 20}]}]', 1);
INSERT INTO `plan_templates` (`name`, `category`, `goal`, `difficulty`, `cycle_type`, `cycle_days`, `description`, `items_json`, `is_official`) VALUES ('减脂 HIIT + 有氧 计划', '减脂', 'lose_fat', 2, 'weekly', 7, '以 HIIT 与低强度有氧交替，配合核心训练，适合想快速减脂的人。', '[{"day_index": 1, "items": [{"exercise": "波比跳", "sets": 4, "reps": 10, "rest_seconds": 45}, {"exercise": "高抬腿", "sets": 4, "reps": 1, "duration_min": 1, "rest_seconds": 30}, {"exercise": "山地登山者", "sets": 4, "reps": 1, "duration_min": 1, "rest_seconds": 30}]}, {"day_index": 2, "items": [{"exercise": "慢跑", "sets": 1, "reps": 1, "duration_min": 30}, {"exercise": "平板支撑", "sets": 3, "reps": 1, "duration_min": 1, "rest_seconds": 45}]}, {"day_index": 4, "items": [{"exercise": "跳绳", "sets": 5, "reps": 1, "duration_min": 2, "rest_seconds": 45}, {"exercise": "仰卧举腿", "sets": 3, "reps": 15, "rest_seconds": 45}]}, {"day_index": 6, "items": [{"exercise": "开合跳", "sets": 5, "reps": 1, "duration_min": 1, "rest_seconds": 30}, {"exercise": "俄罗斯转体", "sets": 3, "reps": 20, "rest_seconds": 45}]}]', 1);
INSERT INTO `plan_templates` (`name`, `category`, `goal`, `difficulty`, `cycle_type`, `cycle_days`, `description`, `items_json`, `is_official`) VALUES ('增肌上下肢 4 日分化', '增肌', 'gain_muscle', 3, 'weekly', 7, '上肢/下肢各两天，给大肌群足够刺激与恢复时间。', '[{"day_index": 1, "items": [{"exercise": "杠铃卧推", "sets": 4, "reps": 8, "rest_seconds": 120}, {"exercise": "杠铃划船", "sets": 4, "reps": 8, "rest_seconds": 120}, {"exercise": "哑铃侧平举", "sets": 3, "reps": 15, "rest_seconds": 60}, {"exercise": "绳索下压", "sets": 3, "reps": 12, "rest_seconds": 60}]}, {"day_index": 2, "items": [{"exercise": "杠铃深蹲", "sets": 5, "reps": 6, "rest_seconds": 150}, {"exercise": "罗马尼亚硬拉", "sets": 4, "reps": 8, "rest_seconds": 120}, {"exercise": "弓箭步", "sets": 3, "reps": 12, "rest_seconds": 90}, {"exercise": "臀桥", "sets": 3, "reps": 15, "rest_seconds": 60}]}, {"day_index": 4, "items": [{"exercise": "上斜哑铃卧推", "sets": 4, "reps": 10, "rest_seconds": 90}, {"exercise": "引体向上", "sets": 4, "reps": 6, "rest_seconds": 120}, {"exercise": "面拉", "sets": 3, "reps": 15, "rest_seconds": 60}, {"exercise": "哑铃弯举", "sets": 3, "reps": 12, "rest_seconds": 60}]}, {"day_index": 5, "items": [{"exercise": "罗马尼亚硬拉", "sets": 4, "reps": 8, "rest_seconds": 120}, {"exercise": "哑铃肩上推举", "sets": 4, "reps": 10, "rest_seconds": 90}, {"exercise": "仰卧举腿", "sets": 3, "reps": 15, "rest_seconds": 45}]}]', 1);
